def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_d = 0
    for x in op:
        if x == 'D':
            opp_d += 1

    if n == 98 and opp_d == 0:
        return 'D'

    last_m = my[-1]
    last_o = op[-1]
    prev_m = my[-2] if n >= 2 else 'C'

    d5 = 0
    start5 = n - 5
    if start5 < 0:
        start5 = 0
    for i in range(start5, n):
        if op[i] == 'D':
            d5 += 1

    d10 = 0
    start10 = n - 10
    if start10 < 0:
        start10 = 0
    for i in range(start10, n):
        if op[i] == 'D':
            d10 += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_d_streak += 1
        else:
            break

    prev_c_count = 0
    prev_d_count = 0
    defect_after_prev_c = 0
    defect_after_prev_d = 0

    for i in range(1, n):
        if my[i - 1] == 'C':
            prev_c_count += 1
            if op[i] == 'D':
                defect_after_prev_c += 1
        else:
            prev_d_count += 1
            if op[i] == 'D':
                defect_after_prev_d += 1

    if opp_d == n:
        return 'D'
    if n >= 5 and d5 >= 4 and opp_d * 2 >= n:
        return 'D'
    if n >= 10 and d10 >= 8 and opp_d * 3 >= n:
        return 'D'
    if n >= 20 and opp_d * 3 >= n * 2:
        return 'D'
    if opp_d_streak >= 5:
        return 'D'
    if prev_c_count >= 5 and defect_after_prev_c * 2 >= prev_c_count and opp_d * 2 >= n:
        return 'D'

    exploitive = False
    if (n >= 8 and prev_c_count >= 3 and defect_after_prev_c >= 2
            and defect_after_prev_c * 2 >= prev_c_count
            and prev_d_count >= 2 and defect_after_prev_d * 2 < prev_d_count):
        exploitive = True

    if last_o == 'C':
        if last_m == 'D' and exploitive:
            return 'D'
        return 'C'

    if last_m == 'D':
        if opp_d_streak >= 3 and opp_d * 2 >= n:
            return 'D'
        if d5 >= 3 and opp_d * 2 >= n:
            return 'D'
        if prev_c_count >= 4 and defect_after_prev_c * 2 >= prev_c_count and opp_d * 2 >= n:
            return 'D'
        if exploitive:
            return 'D'
        return 'C'

    if n >= 2 and prev_m == 'D':
        if opp_d_streak >= 3 and opp_d * 2 >= n:
            return 'D'
        if d5 >= 3 and opp_d * 2 >= n:
            return 'D'
        if prev_c_count >= 4 and defect_after_prev_c * 2 >= prev_c_count and opp_d * 2 >= n:
            return 'D'
        return 'C'

    return 'D'
